class Solution {
public:
    int numberOfNodes(int n, vector<int>& queries) {
        vector<int> flip(n + 1);
        for (int x : queries) if (x <= n) flip[x] ^= 1;
        int answer = 0;
        for (int i = 1; i <= n; ++i) {
            if (i > 1) flip[i] ^= flip[i / 2];
            answer += flip[i];
        }
        return answer;
    }
};
